export function CssRule({
  background = "{{background}}",
  textColor = "{{textColor}}",
  radius = {{radius}},
  applied = {{applied}},
}) {
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", width: 300 }}
      role="img" aria-label="A CSS rule shown as code, applied or not applied to a matching element below">
      <pre style={{ background: "#241430", color: "#FAF7F2", padding: 12, borderRadius: 8,
        font: "12px/1.6 ui-monospace, monospace", whiteSpace: "pre-wrap", margin: "0 0 16px" }}>
{`.box {\n  background: ${background};\n  color: ${textColor};\n  border-radius: ${radius}px;\n}`}
      </pre>
      <div style={{ padding: 16, fontWeight: 600, textAlign: "center",
        border: applied ? "1.5px solid #24143055" : "1.5px dashed #24143055",
        ...(applied ? { background, color: textColor, borderRadius: radius } : {}) }}>
        .box
      </div>
      <p style={{ margin: "12px 0 0", fontSize: 12, color: "#241430cc" }}>
        {applied ? "Rule applied — .box now matches the declarations above." : "Rule not applied — .box keeps the browser's default look."}
      </p>
    </div>
  );
}
